import type { Client } from "@colyseus/core";
import type { Dealer } from "../../../engine/Dealer.js";
import type { PokerState } from "../../../state/PokerState.js";
import { logger } from "../../../lib/logger.js";

// Architectural boundary: room services depend on this facade, never on PokerRoom directly.
// Keep this broad for low-churn extraction safety; tighten incrementally as services stabilize.
export type PokerRoomFacade = any;

export type PokerRoomContext = {
  room: PokerRoomFacade;
  roomId: string;
  dealer: Dealer;
  state: PokerState;
  logger: typeof logger;
  startStallMonitor(): void;
  updateCreateMetadata(cfg?: any): void;
  registerVoiceRelay(): void;
  setSessionEventUnbind(unbind: () => void): void;
  touchActivity(): void;
  bootstrapPersistentSeatRecovery(): Promise<void>;
  disposeRoom(): void;
  addTablePresence(client: Client, userId: string, displayName?: string): void;
  removeTablePresence(userId: string): void;
  handleEmptyStateChange(): void;
  scheduleIdleDispose(): void;
  runPersistentSeatCleanup(): Promise<void>;
  runSittingOutSweep(options?: { nowTs?: number; abandonedPurgeMs?: number }): Promise<{ purgedUserIds: string[] }>;
  seedInstantBots(
    presetId: "MULTIPLAYER_RING" | "HEADS_UP_BOT",
    targetBotCountOverride?: number,
  ): Promise<{ ok: boolean; added: number; target: number; reason?: string }>;
  maybeRemoveBotsIfNoHumans(): Promise<void>;
  purgeBotsForDelete(): void;
};

export interface PokerRoomAuthService {
  authenticate(client: Client, options: any, context: { token?: string; headers?: Headers }): Promise<any>;
}

export interface PokerRoomJoinServiceContract {
  handleJoin(client: Client, options: any, auth?: any): Promise<void>;
}

export interface PokerRoomLeaveServiceContract {
  handleLeave(client: Client, code?: number): Promise<void>;
}

export interface PokerRoomMessageRouterContract {
  registerAll(): void;
}

export interface PokerRoomLifecycleContract {
  setup(options?: { cfg?: any }): void;
  dispose(): void;
}

import type { Room } from "@colyseus/core";
import { VOICE_SIGNAL_TYPE } from "../../voice/contracts/voice-signals.js";
import { parseVoiceSignalMessage } from "./voice-signal-schema.js";
import { getClientUserId } from "./voice-client-identity.js";
import { shouldAllowVoiceRelay } from "./voice-feature-flag.js";
import { createVoiceRateLimiter } from "./voice-rate-limit.js";
import { getMessageByteSize } from "./voice-size-guard.js";
import { logger } from "../../lib/logger.js";

/**
 * register -> voice relay
 * Adds a message handler to the PokerRoom to forward VOICE signals:
 * - validate
 * - rate-limit
 * - size limit
 * - targeted forward to recipient only
 *
 * This MUST stay lightweight for free Railway servers.
 */
export function registerVoiceRelay(room: Room) {
  const limiter = createVoiceRateLimiter();

  room.onMessage(VOICE_SIGNAL_TYPE, (client: any, raw: any) => {
    if (!shouldAllowVoiceRelay()) return;

    const size = getMessageByteSize(raw);
    if (size > 32_000) {
      logger.warn({ size }, "VOICE_SIGNAL dropped (too large)");
      return;
    }

    const userId = getClientUserId(client);
    if (!userId) return;

    if (!limiter.allow(client.sessionId)) {
      logger.warn({ sessionId: client.sessionId }, "VOICE_SIGNAL dropped (rate limited)");
      return;
    }

    const msg = parseVoiceSignalMessage(raw);
    if (!msg) return;

    // Basic anti-spoof: enforce fromUserId matches this client userId.
    if (msg.fromUserId !== userId) {
      logger.warn({ userId, fromUserId: msg.fromUserId }, "VOICE_SIGNAL dropped (spoof)");
      return;
    }

    if (msg.toUserId === msg.fromUserId) {
      logger.warn({ userId, toUserId: msg.toUserId }, "VOICE_SIGNAL dropped (self-loop)");
      return;
    }

    // Channel policy: default uses roomId as channel, but we keep it flexible.
    // In poker-champ, channelId should be tableId.
    const roomChannel = (room as any).state?.tableId ?? (room as any).roomId;
    if (msg.channelId !== roomChannel) {
      logger.warn({ roomChannel, msgChannel: msg.channelId }, "VOICE_SIGNAL dropped (wrong channel)");
      return;
    }

    // Targeted forward
    const recipient = room.clients.find((c: any) => getClientUserId(c) === msg.toUserId);
    if (!recipient) return;

    recipient.send(VOICE_SIGNAL_TYPE, msg);
  });
}

/**
 * get -> client userId
 * Update this function to match your auth wiring.
 *
 * Common patterns:
 * - client.auth?.userId
 * - client.userData?.userId
 * - client.userId
 */
export function getClientUserId(client: any): string | null {
  return (
    client?.auth?.userId ??
    client?.userData?.userId ??
    client?.userId ??
    null
  );
}
